export function cropImage(image,t){return new Promise(resolve=>{const d=document.createElement('dialog');d.className='crop-dialog';d.innerHTML='<h2 id="cropTitle"></h2><p class="crop-help"></p><canvas width="300" height="300" tabindex="0"></canvas><label>Zoom<input name="zoom" type="range" min="1" max="4" step="0.01" value="1"></label><label>X<input name="x" type="range" min="0" max="100" value="50"></label><label>Y<input name="y" type="range" min="0" max="100" value="50"></label><div class="button-row"><button type="button" class="secondary-cta" data-crop="cancel"></button><button type="button" class="small-primary" data-crop="confirm"></button></div>';d.setAttribute('aria-labelledby','cropTitle');document.body.append(d);d.querySelector('h2').textContent=t('cropTitle');d.querySelector('.crop-help').textContent=t('cropHint');d.querySelector('[data-crop=cancel]').textContent=t('cancel');d.querySelector('[data-crop=confirm]').textContent=t('cropConfirm');const c=d.querySelector('canvas'),ctx=c.getContext('2d'),x=d.querySelector('[name=x]'),y=d.querySelector('[name=y]'),z=d.querySelector('[name=zoom]');let drag=null;function draw(){const size=Math.min(image.width,image.height)/Number(z.value),sx=(image.width-size)*Number(x.value)/100,sy=(image.height-size)*Number(y.value)/100;ctx.drawImage(image,sx,sy,size,size,0,0,300,300);}d.addEventListener('input',draw);c.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,px:Number(x.value),py:Number(y.value)};c.setPointerCapture(e.pointerId);};c.onpointermove=e=>{if(!drag)return;x.value=Math.max(0,Math.min(100,drag.px-(e.clientX-drag.x)/2));y.value=Math.max(0,Math.min(100,drag.py-(e.clientY-drag.y)/2));draw();};c.onpointerup=()=>drag=null;const finish=value=>{d.close();d.remove();resolve(value);};d.addEventListener('cancel',e=>{e.preventDefault();finish(null);});d.onclick=e=>{if(e.target.dataset.crop==='cancel')finish(null);if(e.target.dataset.crop==='confirm'){const out=document.createElement('canvas');out.width=256;out.height=256;out.getContext('2d').drawImage(c,0,0,256,256);finish(out.toDataURL('image/jpeg',.84));}};d.showModal();draw();d.querySelector('[data-crop=confirm]').focus();});}
